input.command:
mkdir -p src/inngest src/app/api/inngest && cat > src/inngest/client.ts <<'EOF'
import { EventSchemas, Inngest } from "inngest";

type Events = {
  "user/created": { data: { userId: string; email: string; name: string } };
};

export const inngest = new Inngest({
  id: "notely",
  schemas: new EventSchemas().fromRecord<Events>(),
});
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const userReminder = inngest.createFunction(
  {
    id: "user-reminder",
    retries: 5,
    triggers: [{ event: "user/created" }],
  },
  async ({ event, step }) => {
    await step.sleep("wait-10-minutes", "10m");

    // Separate step so a failure here retries without re-sleeping.
    await step.run("log-reminder", async () => {
      const { userId, email, name } = event.data;
      console.log(`[reminder] ${name} <${email}> (user ${userId}) signed up 10 minutes ago`);
    });
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
cat > .env.example <<'EOF'
# Inngest (https://app.inngest.com). Not needed for local dev with the Dev Server.
INNGEST_EVENT_KEY=placeholder-event-key
INNGEST_SIGNING_KEY=signkey-prod-placeholder

# Local dev: run `npx inngest-cli@latest dev` and set:
# INNGEST_DEV=1
EOF
printf '!.env.example\n' >> .gitignore
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='import { inngest } from "@/inngest/client";\n\n'+s
s=s.replace('''export async function getUser''','''export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString(),
  };
  users.push(user);

  // The function sleeps 10 minutes, then logs the reminder (with retries).
  await inngest.send({
    name: "user/created",
    data: { userId: user.id, email: user.email, name: user.name },
  });

  return user;
}

export async function getUser''',1)
open(p,'w').write(s)
EOF
npx tsc --noEmit && npm run lint 2>&1 | tail -5

